import React from 'react';

const TableViewComponent = ({ results }) => {
  if (!results || !results.length) {
    return <div>No results found.</div>;
  }

  return (
    <table className="results-table table-auto w-full border-collapse border border-gray-300 dark:border-gray-700">
      <thead className="bg-gray-100 dark:bg-gray-800">
        <tr>
          <th className="border p-2 w-32">Image</th>
          <th className="border p-2">Details</th>
        </tr>
      </thead>
      <tbody>
        {results.map((result, index) => (
          <tr key={index} className="border-t hover:bg-gray-50 dark:hover:bg-gray-900">
            {/* Column 1: Image */}
            <td className="border p-2 align-top">
              {result.page_image_ext ? (
                <a
                  href={result.full_title}
                  className="block w-20 h-20 bg-cover bg-center rounded border border-gray-300 dark:border-gray-600"
                  style={{ backgroundImage: `url(${result.page_image_ext})` }}
                  title={result.title}
                ></a>
              ) : (
                <div className="w-20 h-20 bg-gray-200 dark:bg-gray-700 rounded" />
              )}
            </td>

            {/* Column 2: Title + Categories + Year */}
            <td className="border p-2 align-top text-sm text-gray-700 dark:text-gray-300">
              {/* Title */}
              <div className="mb-1">
                <a
                  href={result.full_title}
                  className="text-blue-600 hover:underline font-semibold dark:text-blue-300"
                >
                  {result.title}
                </a>
              </div>

              {/* Categories as tags */}
              {Array.isArray(result.category) && result.category.length > 0 && (
                <div className="flex flex-wrap items-center gap-2 mb-1">
                  <i className="fal fa-tags text-gray-400"></i>
                  {result.category.map((cat, i) => (
                    <a
                      key={i}
                      href={`/${cat.link}`}
                      className="px-2 py-0.5 bg-blue-100 text-blue-700 rounded text-xs hover:underline dark:bg-blue-800 dark:text-blue-200"
                      title={`Category: ${cat.name}`}
                    >
                      {cat.name}
                    </a>
                  ))}
                </div>
              )}

              {/* Year */}
              {result.year && (
                <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400">
                  <i className="fal fa-pencil-alt"></i>
                  <span>{result.year}</span>
                </div>
              )}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

export default TableViewComponent;
